import '../styles/Cart.css';
import { useState } from 'react';

function Cart({ cart, updateCart }) {
    const tshirtPrice = 20;

    return (
        <div className='cart'>
            <h2>Panier</h2>
            <ul>
                {cart.map(({ name, price, amount }, index) => (
                    <div>
                        {name} {price} X {amount} <br />
                    </div>
                ))}
            </ul>
            <div className="total">
                
                Total : {total} €
            </div>
            <br />
            <button onClick={() => updateCart([])}>
                Vider le panier
            </button>
        </div>
    );
}


export default Cart
